def references_board(r):
    s=core.Board();s.heading('Новые ориентиры: функция и подача','Автор выбрала два предметных направления и отдельный пример стиля. На листе - именно присланные референсы; это не собственные разработки диплома.')
    for i,a in enumerate(r['references']):
        x=12+134*i;s.text(x,49,a['title'],14,core.C['teal'],True);s.picture(a['image'],x,56,128,112)
        s.note(x,181,125,'Что видно',a['visible']);s.note(x,215,125,'Что переношу в разработку',a['take']);s.para(x,256,125,a['check'],10.2,4.3,max_lines=7)
    return s

def functions_board(m):
    s=core.Board();s.heading('Общий набор: какую задачу решает каждая часть','Четыре функции выведены из действий. Для каждого варианта отдельно проверяю, какие функции он действительно обеспечивает. Цвет и материал пока не выбираю.')
    photos=['research/assets/age-groups/child-6.jpg','research/assets/board-1/nhs-sit-to-stand.jpg','research/assets/age-groups/older-calf.jpg','design/references/2026-11-06/01-bench-storage.png']
    short=[
      'Панель лежит на полу. Ребёнок и молодой взрослый опираются на неё ладонями, коленями или спиной. Сиденье для этих действий не требуется.',
      'Посадка и вставание требуют подходящей высоты, места для стоп и наклона тела. Это одна из основных функций для пожилого пользователя.',
      'Поддержка стоя требует отдельного удобного хвата. На фото используется стул из источника; пригодность нашего будущего предмета ещё нужно доказать.',
      'У каждого предмета есть понятное место. Тяжёлые предметы отделяются от лёгких; закрывание и доступ ребёнка нужно продумать. На фото - референс автора.']
    for i,f in enumerate(m['functions']):
        x=12+202*(i%2);y=48+119*(i//2)
        s.rect(x,y,194,111,'#F7FAF9',core.C['light'],.25);s.text(x+4,y+10,f['name'],13,core.C['teal'],True)
        s.picture(photos[i],x+3,y+15,188,55);s.para(x+4,y+77,186,short[i],11,4.7,max_lines=6)
    return s

def concept_board(c,no_drill=False):
    s=core.Board();title={'R1':'Эскиз 1. Скамья с хранением','R2':'Эскиз 2. Настенная система'}[c['id']]
    if no_drill and c['id']=='R2':title='Эскиз 2. Напольный модуль у стены'
    s.heading(title,'Собственный поисковый эскиз по выбранным ориентирам: тонкая линия, сдержанный цвет, несколько состояний. Материалы, размеры, крепления и нагрузки не утверждены.')
    s.picture(c['image'],12,49,274,183)
    for n,(x,y) in enumerate([(16,52),(153,52),(16,144),(153,144)],1):s.marker(x,y,n)
    if c['id']=='R1':
        rows=[('Наклон как возможность',c['what']),('Посадка',c['older']),('Действие на полу',c['young']),('Крупные части',c['parts'])]
    else:rows=[('Хранение закрыто',c['what']),('Посадка',c['older']),('Ребёнок',c['child']),('Вернуть инвентарь',c['young'])]
    for i,(head,body) in enumerate(rows):
        y=52+i*47;s.marker(295,y-1,i+1);s.text(302,y,head,12.1,core.C['teal'],True);s.para(294,y+7,113,body,10.4,4.3,max_lines=8)
    s.note(12,249,123,'Что даёт направление',c['strength']);s.note(146,249,123,'Что пока не решено',c['weakness']);s.note(280,249,126,'Что проверить первым',c['checks'])
    return s

def checks_board(m,no_drill=False):
    s=core.Board();s.heading('Следующий шаг: проверить место тела и доступ','Новые размеры не назначаю по картинке. Сначала фиксирую крайние положения и весь цикл подготовки. Габарит корпуса и место для занятия записываю отдельно.')
    rows=[
      ('C1','Вытягивание на полу','Отметить край вытянутой руки и стопы, положение ладони и колена. Проверить длину панели и место шва. Корпус хранения находится вне этой траектории.'),
      ('Y3','Движение рядом с корпусом','Отметить край головы, таза и гантелей при наклоне. Добавить подход к месту хранения и возвращение предмета. Открытая дверца тоже занимает место.'),
      ('O1','Посадка и вставание','Проверить стопы на полу, глубину посадки, колени и наклон вперёд. Для настенной версии добавить разложенное сиденье, обе ножки и место помощника при необходимости.'),
      ('O2','Поддержка рукой','Выбрать положение хвата и путь подхода к нему. Отдельно проверить передачу усилия в корпус, стену или пол. У двух новых эскизов эта функция пока не доказана.')]
    if no_drill:
        rows[2]=('O1','Посадка и вставание','Проверить стопы на полу, глубину посадки, колени и наклон вперёд. Для модуля у стены добавить основание, разложенное сиденье, обе ножки и место помощника при необходимости.')
        rows[3]=('O2','Поддержка рукой','Выбрать положение хвата и путь подхода к нему. Усилие должно переходить через собственный корпус и основание в пол. Стена не служит опорой. Устойчивость ещё нужно проверить.')
    for i,(key,head,body) in enumerate(rows):
        a=next(x for x in m['movements'] if x['id']==key);x=12+202*(i%2);y=48+119*(i//2)
        s.rect(x,y,194,111,'#F7FAF9',core.C['light'],.25);s.text(x+4,y+10,head,13,core.C['teal'],True);s.picture(a['image'],x+3,y+15,188,52);s.para(x+4,y+75,186,body,11,4.7,max_lines=7)
    return s

def comparison_board(r):
    no_drill=r.get('installation_method')=='floor_standing_no_drill'
    second='Модуль у стены' if no_drill else 'Настенная система'
    s=core.Board();s.heading('Сравнение: скамья или модуль у стены' if no_drill else 'Сравнение: скамья или настенная система','Все три группы остаются в задании. Ни одно направление пока не выбрано окончательно; картинки помогают увидеть различия и выбрать следующий натурный опыт.')
    for i,c in enumerate(r['concepts']):
        x=74+166*i;s.text(x,49,['Скамья',second][i],14,core.C['teal'],True);s.picture(c['image'],x,53,160,85)
    xs=[12,106,257];ws=[94,151,151];y=146
    rows=[
      ['Что сравниваю','Скамья','Настенная система'],
      ['Место в комнате','Корпус постоянно занимает пол; зона действия рядом','Хранение вдоль стены; открытое сиденье всё равно занимает пол'],
      ['Ребёнок / молодой взрослый','Вынутая панель и отдельный инвентарь','Та же роль панели и предметов; сиденье закрыто'],
      ['Пожилой пользователь','Постоянное сиденье; посадку подобрать','Открыть сиденье и передние опоры; подготовку проверить'],
      ['Поддержка стоя','Отдельный хват и устойчивость ещё не проработаны','Отдельный хват и крепление ещё не проработаны'],
      ['Дополнительный механизм','Наклонная часть: пока нет выбранного действия на ней','Складное сиденье: нужно для показанной посадки'],
      ['Главный вопрос','Полезен ли наклон и удобнее ли общий корпус отдельных предметов?','Допустимо ли крепление к стене и удобна ли подготовка сиденья?']]
    if no_drill:
        rows[0][2]=second
        rows[1][2]='Своя напольная база занимает пол постоянно; открытое сиденье добавляет место'
        rows[4][2]='Отдельный хват и устойчивость собственной базы ещё не проверены'
        rows[6][2]='Устойчив ли корпус без стены и удобна ли подготовка сиденья?'
    for j,row in enumerate(rows):
        h=12 if j==0 else 17;s.rect(12,y,396,h,core.C['pale'] if j%2==0 else '#F8FAFA')
        for i,t in enumerate(row):s.para(xs[i]+2,y+5,ws[i]-4,t,10.2,4.1,bold=j==0 or i==0,max_lines=3)
        y+=h+1
    s.para(12,276,258,'Дальше: проверить посадку, вытягивание тела и доступ на полноразмерной компоновке; затем сравнить подготовку и уборку. Крепления и прочность - отдельный этап.',10.6,4.5,bold=True,color=core.C['teal'],max_lines=4)
    s.para(280,276,126,'Установка без сверления подтверждена. Модуль стоит на полу; стена не несёт его нагрузку. Устойчивость ещё не доказана.' if no_drill else 'Наклон, материалы и настенный способ установки показаны как гипотезы. Прежнее условие без сверления уточняется.',10.3,4.3,max_lines=4)
    return s

def report_pages(m,r):
    no_drill=r.get('installation_method')=='floor_standing_no_drill'
    pages=core.report_pages(m)
    first=pages[0]['sections'][0]
    pages[0]['sections'][0]=(first[0],'Я отобрала девять действий для сравнения: по три на каждую обязательную группу. Связала их с частями изделия, разобрала полезные приёмы аналогов и после новых референсов автора предложила два направления: скамью с хранением и настенную систему со складным сиденьем. На рисунках показаны состояния, люди и крупные части.')
    pages[0]['sections'][2]=('Что общее у двух направлений','Напольная панель, подходящее сиденье и организованное хранение. Отдельно требуется поддержка рукой: в новых эскизах она ещё не проработана. Нельзя считать, что наличие корпуса или стены автоматически обеспечивает нужный хват и устойчивость. Функции проверяю по каждой конструкции отдельно.')
    pages[5]['title']='Два направления после референсов'
    pages[5]['sections']=[(c['name'],c['what']+'\nПуть усилия: '+c['loadpath']+'\nВопрос: '+c['weakness']) for c in r['concepts']]+[
      ('Что это меняет в задании','Наклонная часть нравится как направление, но для девяти выбранных действий она не обязательна. Не добавляю новое упражнение только ради механизма. Настенное хранение само по себе не даёт сиденья: складную опору предлагаю отдельно. Поддержка рукой требует дальнейшего эскиза. Два направления сравниваются, ни одно не утверждено.'),
      ('Как понимать разнесённые части','На эскизе скамьи разделены опоры, подушки и хранение. Это объяснение крупных частей, не ведомость деталей. Соединения, фиксаторы и материал ещё не назначены.')]
    pages[6]['sections'][1]=('Молодой взрослый → пожилой','Вернуть гантели, убрать панель с подхода и проверить место стоп. У скамьи оставить горизонтальное состояние; у настенной версии развернуть сиденье и обе передние опоры, затем проверить фиксацию. Выяснить, может ли пользователь подготовить систему сам или ему нужна помощь.')
    pages.insert(1,dict(title='Что беру из трёх референсов',sections=[(a['title'],a['visible']+'\nВ разработку: '+a['take']+'\nГраница вывода: '+a['check']) for a in r['references']]+[
      ('Настенная установка',r['installation']+' На эскизе не назначены анкеры или основание стены. Если сверление останется недопустимым, подвесную конструкцию нельзя молча выдать за готовый вариант без сверления: потребуется другое решение.'),
      ('Цвет и стиль','Беру из третьей картинки характер подачи: белый фон, линия, спокойные цветовые пятна и показ частей. Коричневый и серый помогают различать поверхности. Они не означают утверждения дерева, кожи или металла. Авторство и характеристики чужих предметов по этим изображениям не установлены.')]))
    if no_drill:
        pages[0]['sections'][0]=(first[0],'Я отобрала девять действий для сравнения: по три на каждую обязательную группу. Связала их с частями изделия, разобрала полезные приёмы аналогов и предложила скамью с хранением и напольный модуль у стены. После уточнения автора убрала подвесную установку: оба направления разрабатываются без сверления.')
        pages[0]['sections'][2]=('Что общее у двух направлений','Напольная панель, подходящее сиденье и организованное хранение. Отдельно требуется поддержка рукой: её ещё нужно проработать. Обе конструкции опираются на пол. Само наличие корпуса не доказывает нужный хват и устойчивость; эти свойства проверяются отдельно.')
        pages[1]['sections'][3]=('Установка без сверления',r['installation']+' Наклеивание или распорные крепления не назначены. Предлагаемая собственная рама - гипотеза для проверки. Напольная база занимает место даже при сложенном сиденье; её размеры и устойчивость ещё не определены.')
        pages[6]['title']='Два направления без сверления'
        pages[6]['sections'][2]=('Что это меняет в задании','Наклонная часть скамьи пока не обязательна для выбранных действий. Из настенного референса беру вертикальное хранение, а опору переношу на собственную напольную раму. Складное сиденье сохраняется как гипотеза. Нужно проверить устойчивость при открывании, посадке и вставании, затем разработать соединения. Ни один вариант не утверждён.')
        pages[7]['sections'][1]=('Молодой взрослый → пожилой','Вернуть гантели, убрать панель с подхода и проверить место стоп. У скамьи оставить горизонтальное состояние; у напольного модуля развернуть сиденье и обе передние опоры, затем проверить фиксацию. Выяснить, может ли пользователь подготовить систему сам или ему нужна помощь. Основание остаётся на полу; опора на стену не предусмотрена.')
    return pages

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--output-dir',type=Path,default=ROOT/'outputs/current');ap.add_argument('--no-drill',action='store_true');a=ap.parse_args();out=a.output_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    stem=STEM+('_v2' if a.no_drill else '');report_name=REPORT+('_v2' if a.no_drill else '')
    target=out/(stem+'.pdf');report=out/(report_name+'.pdf');htmlpath=out/(stem+'.html')
    if any(p.exists() for p in [target,report,htmlpath]):raise FileExistsError('Existing deliverables will not be overwritten')
    pdfmetrics.registerFont(TTFont('Spatial','C:/Windows/Fonts/arial.ttf'));pdfmetrics.registerFont(TTFont('SpatialBold','C:/Windows/Fonts/arialbd.ttf'))
    model='reference-update-2026-11-06_v2.json' if a.no_drill else 'reference-update-2026-11-06.json'
    m=json.loads(core.MODEL.read_text(encoding='utf-8'));r=json.loads((ROOT/'research'/model).read_text(encoding='utf-8'));m['concepts']=r['concepts']
    if a.no_drill:m['stage']='Уточнение S-этапа по D-025: установка без сверления. Сравниваются две конструкции с собственной опорой на пол; устойчивость ещё не проверена.'
    boards=[references_board(r),core.movement_board(m),core.analog_board(m),functions_board(m)]+[concept_board(c,a.no_drill) for c in r['concepts']]+[checks_board(m,a.no_drill),comparison_board(r)]
    pdf=canvas.Canvas(str(target),pagesize=(420*mm,297*mm));pdf.setTitle('Функции и эскизы по выбранным референсам');pdf.setAuthor('Диплом: этап S');vectors=[]
    for i,b in enumerate(boards,1):
        core.draw_pdf(pdf,b);pdf.showPage();v=core.board_svg(b);vectors.append(v);(out/f'{stem}_{i:02d}.svg').write_text(v,encoding='utf-8')
    pdf.save()
    html='<!doctype html><html lang="ru"><meta charset="utf-8"><title>Функции и эскизы</title><style>@page{size:A3 landscape;margin:0}body{margin:0;background:#ddd}.sheet{width:420mm;height:297mm;margin:10px auto;break-after:page;background:white}svg{display:block}@media print{body{background:white}.sheet{margin:0}}</style>'+''.join('<div class="sheet">'+v+'</div>' for v in vectors)+'</html>'
    htmlpath.write_text(html,encoding='utf-8')
    core.build_report(m,out,pages_override=report_pages(m,r),report_name=report_name)
    build=ROOT/'.codex-build/s-rank-2026-11-06';(build/('reference-layout-v2.json' if a.no_drill else 'reference-layout.json')).write_text(json.dumps([b.e for b in boards],ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'a3_pages':len(boards),'a4_expected_pages':9,'a3_pdf':str(target),'a4_pdf':str(report)}))

if __name__=='__main__':main()
